export function getRuntimeInteraction(
  interactionId: RuntimeInteractionId
): RuntimeInteraction | undefined {
  const all = [
    ...EVE_04_RUNTIME_CATALOG.modules.runtime_interactions_base_40,
    ...EVE_04_RUNTIME_CATALOG.modules.runtime_interactions_causal_20,
  ] as unknown as RuntimeInteraction[];
  return all.find((item) => item.runtime_interaction_id === interactionId);
}

export function getResolvedVariableDefinition(variableName: string) {
  return EVE_04_RUNTIME_CATALOG.support.canonical_variable_definitions_resolved.find(
    (item) => item.variable === variableName
  );
}

export function selectCausalInteractions(
  signals: readonly CausalSignal[],
  alreadyShown: number,
  limit = EVE_04_RUNTIME_CATALOG.modules.branching_budget_rules
    .max_causal_interactions_per_activity
): string[] {
  const remaining = Math.max(0, limit - alreadyShown);
  return signals
    .filter((signal) => signal.requiresUserInput && signal.score > 0)
    .slice()
    .sort((a, b) => {
      if (Boolean(a.routeCritical) !== Boolean(b.routeCritical)) {
        return a.routeCritical ? -1 : 1;
      }
      if (a.score !== b.score) return b.score - a.score;
      return Number(b.severity ?? 0) - Number(a.severity ?? 0);
    })
    .slice(0, remaining)
    .map((signal) => signal.signalId);
}

export function canParallelProductionConsume(state: ReadinessState): boolean {
  return state === "ready" || state === "ready_with_flags";
}

export function validateRuntimeCatalog(): string[] {
  const issues: string[] = [];
  const base = EVE_04_RUNTIME_CATALOG.modules.runtime_interactions_base_40;
  const causal = EVE_04_RUNTIME_CATALOG.modules.runtime_interactions_causal_20;
  const all = [...base, ...causal] as unknown as RuntimeInteraction[];
  const ids = all.map((item) => item.runtime_interaction_id);

  if (base.length !== 40) issues.push(`Expected 40 base interactions; got ${base.length}.`);
  if (causal.length !== 20) issues.push(`Expected 20 causal interactions; got ${causal.length}.`);
  if (new Set(ids).size !== ids.length) issues.push("Duplicate runtime interaction IDs.");
  if (all.some((item) => !item._lineage.phase3_source_nodes_resolved)) {
    issues.push("At least one interaction has unresolved source nodes.");
  }
  if (all.some((item) => item._lineage.phase3_pending_variable_refs.length > 0)) {
    issues.push("At least one interaction still has pending variable definitions.");
  }

  const unmapped = EVE_04_RUNTIME_CATALOG.support.source_node_coverage.filter(
    (node) => node.coverage_status.startsWith("unmapped")
  );
  if (unmapped.length > 0) {
    issues.push(
      `Canonical source coverage is incomplete: ${unmapped
        .map((node) => node.source_node_ref_id)
        .join(", ")}.`
    );
  }

  const definitions =
    EVE_04_RUNTIME_CATALOG.support.canonical_variable_definitions_resolved;
  if (definitions.length !== 33) {
    issues.push(`Expected 33 recovered variable definitions; got ${definitions.length}.`);
  }

  const b6q38 = getRuntimeInteraction("B6-Q38");
  if (
    !b6q38 ||
    !b6q38.source_nodes.includes("B6_6_8") ||
    !b6q38.canonical_variables.includes("trench_phrase")
  ) {
    issues.push("CCOV-001 correction is missing from B6-Q38.");
  }

  return issues;
}

export default EVE_04_RUNTIME_CATALOG;
